/**
 * LEAD-DB bulk loader — import a large CSV or JSON file of leads into a named
 * EmailList, server-side, using the SAME idempotent dedup/ingest logic as the
 * admin importer (lib/coldemail/import.ts + lib/coldemail/lead-store.ts). Use this
 * instead of the web importer for big files (tens of thousands of rows) — there's
 * no request timeout here.
 *
 * IDEMPOTENT: re-running the same file inserts 0 (all rows match existing and are
 * updated in place). DEAD/suppressed contacts are never resurrected.
 *
 * Usage:
 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Q3 prospects"
 *   npx tsx scripts/import-leads.ts --file leads.json --list-id <listId> --consent
 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Cold UK" --create-list
 *
 * Flags:
 *   --file <path>        CSV or JSON file (JSON = array of objects; keys use the
 *                        same header names/aliases as CSV). Required.
 *   --list <name>        Target list by name. Errors if ambiguous/absent unless
 *                        --create-list is given.
 *   --list-id <id>       Target list by id (takes precedence over --list).
 *   --create-list        Create the list (by --list name) if it doesn't exist.
 *   --consent            Record a LEGITIMATE_INTEREST consent row for each NEW contact.
 *   --note <text>        Provenance note stored on the ImportBatch — how/where this
 *                        batch was sourced (e.g. "Manual research via <directory URL>,
 *                        2026-08-25"). ALWAYS pass this for a research-sourced batch;
 *                        it's the only batch-level record of provenance (see the
 *                        `sourceUrl` column for PER-CONTACT provenance, below).
 *   --dry-run            Parse + report row counts only; write nothing.
 *
 * CSV headers spec: see docs/DOCUMENTATION.md (Lead database → Import). Minimum: an
 * `email` column. Everything else (name, fullName, title, website, phone, city, …)
 * is optional and mapped through IMPORT_HEADER_ALIASES. A `source`/`sourceUrl` column
 * (the specific URL this contact's email was found on) is recorded on that contact's
 * ConsentRecord.note when --consent is passed, so provenance is checkable per-contact.
 */
import { readFileSync } from "node:fs";
import { db } from "../lib/db";
import {
  ingestLeads,
  parseCsv,
  csvToLeadRows,
  IMPORT_HEADER_ALIASES,
  type LeadRow,
} from "../lib/coldemail/import";
import { prismaLeadStore } from "../lib/coldemail/lead-store";

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i !== -1 ? process.argv[i + 1] : undefined;
}
function flag(name: string): boolean {
  return process.argv.includes(`--${name}`);
}

/** Map an arbitrary JSON object's keys onto canonical LeadRow fields via the aliases. */
function jsonObjToLeadRow(obj: Record<string, unknown>): LeadRow {
  const lead: LeadRow = {};
  for (const [k, v] of Object.entries(obj)) {
    const field = IMPORT_HEADER_ALIASES[k.trim().toLowerCase()];
    if (field && v != null) lead[field] = String(v).trim();
  }
  return lead;
}

async function main(): Promise<void> {
  const filePath = arg("file");
  if (!filePath) {
    console.error("ERROR: --file <path> is required. See the header of this script for usage.");
    process.exit(1);
  }

  const listName = arg("list");
  const listIdArg = arg("list-id");
  const createList = flag("create-list");
  const recordConsent = flag("consent");
  const dryRun = flag("dry-run");
  const note = arg("note") ?? "";

  // ---- Load + parse the file into LeadRow[] ----
  const raw = readFileSync(filePath, "utf8");
  let rows: LeadRow[];
  if (filePath.toLowerCase().endsWith(".json")) {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) throw new Error("JSON file must be an array of lead objects.");
    rows = parsed.map((o) => jsonObjToLeadRow(o as Record<string, unknown>));
  } else {
    const { headers, rows: csvRows } = parseCsv(raw);
    if (headers.length === 0) throw new Error("Could not parse a header row from the CSV.");
    rows = csvToLeadRows(headers, csvRows);
  }
  console.log(`Parsed ${rows.length} row(s) from ${filePath}.`);

  if (dryRun) {
    console.log("--dry-run: no changes written.");
    await db.$disconnect();
    return;
  }

  // ---- Resolve the target list ----
  let listId: string | null = null;
  if (listIdArg) {
    const list = await db.emailList.findUnique({ where: { id: listIdArg }, select: { id: true } });
    if (!list) throw new Error(`No list with id ${listIdArg}.`);
    listId = list.id;
  } else if (listName) {
    const matches = await db.emailList.findMany({ where: { name: listName }, select: { id: true } });
    if (matches.length === 1) listId = matches[0].id;
    else if (matches.length === 0) {
      if (!createList) throw new Error(`No list named "${listName}". Pass --create-list to create it.`);
      const created = await db.emailList.create({ data: { name: listName }, select: { id: true } });
      listId = created.id;
      console.log(`Created list "${listName}" (${listId}).`);
    } else {
      throw new Error(`"${listName}" is ambiguous (${matches.length} lists). Use --list-id.`);
    }
  } else {
    console.log("No --list/--list-id given — importing into the lead DB without list assignment.");
  }

  // ---- Ingest via the shared, idempotent core ----
  const batch = await db.importBatch.create({
    data: {
      name: `Script import ${new Date().toISOString().slice(0, 16)}`,
      source: "script",
      listId,
      note,
    },
    select: { id: true },
  });

  const result = await ingestLeads(rows, {
    store: prismaLeadStore("script"),
    listId,
    batchId: batch.id,
    recordConsent,
    consentSource: "script import",
  });

  await db.importBatch.update({
    where: { id: batch.id },
    data: {
      totalRows: result.totalRows,
      inserted: result.inserted,
      updated: result.updated,
      skippedDead: result.skippedDead,
      skippedDup: result.skippedDup,
      skippedInvalid: result.skippedInvalid,
    },
  });

  console.log("Import complete:");
  console.log(`  inserted (new):          ${result.inserted}`);
  console.log(`  updated (existing):      ${result.updated}`);
  console.log(`  skipped dead/suppressed: ${result.skippedDead}`);
  console.log(`  skipped in-file dupes:   ${result.skippedDup}`);
  console.log(`  skipped invalid (no email): ${result.skippedInvalid}`);
  console.log(`  batch id: ${batch.id}`);

  await db.$disconnect();
}

main().catch(async (err) => {
  console.error("Import failed:", err?.message ?? err);
  await db.$disconnect().catch(() => null);
  process.exit(1);
});
