// Cold Email Engine — LEAD-DATABASE bulk import + continuous ingestion core.
//
// PURE ORCHESTRATION over an injected `LeadStore` so the exact same idempotent
// dedup/ingest logic runs from (a) the admin server action, (b) the operator CLI
// script scripts/import-leads.ts, and (c) the tests (with an in-memory store, no
// DB). The store is the ONLY thing that touches Prisma.
//
// IDEMPOTENCY + HYGIENE GUARANTEES:
//   - Dedup by NORMALIZED email (primary key of a lead). A repeat of an email
//     already seen earlier in the same file is skipped (skippedDup).
//   - An incoming email that matches an existing contact UPDATES it (fills blanks,
//     re-adds to the target list) — never inserts a duplicate. So a re-import of
//     the same file inserts 0.
//   - An incoming email that matches an existing DEAD or globally-SUPPRESSED
//     contact is NOT resurrected (skippedDead) — no update, no re-add to a list.
//   - A brand-new email that is already on the global suppression list is refused
//     (skippedDead) — we never add a suppressed address.
//   - Secondary signal: phone/website(domain) are recorded on the Business but the
//     dedup key is always the email (the only reliable per-person identifier).

import { normalizeEmail, emailDomain, normalizeDomain } from "@/lib/coldemail/compliance";
import { isDeadStatus, type EmailStatusValue } from "@/lib/coldemail/leaddb";

// ---------------------------------------------------------------------------
// Row model + header spec
// ---------------------------------------------------------------------------

/**
 * Canonical field names an import row can carry. The CSV header row is mapped onto
 * these via IMPORT_HEADER_ALIASES; a JSON array uses these keys directly.
 */
export type LeadRow = {
  email?: string;
  fullName?: string;
  title?: string;
  // Business fields:
  name?: string; // business name
  category?: string;
  businessType?: string;
  website?: string;
  phone?: string;
  addressLine?: string;
  city?: string;
  region?: string;
  country?: string;
  companySize?: string;
  // Provenance: the specific URL/page this contact's email was found on. Not stored on
  // the Contact/Business row — threaded through to the per-contact ConsentRecord.note so
  // a batch's lawful-basis evidence is checkable one contact at a time (see recordConsent).
  sourceUrl?: string;
};

/**
 * Header alias → canonical field. Superset of the legacy Businesses importer so old
 * files keep working. Keys are compared lower-cased + trimmed.
 */
export const IMPORT_HEADER_ALIASES: Record<string, keyof LeadRow> = {
  email: "email",
  "email address": "email",
  "e-mail": "email",
  contactemail: "email",
  fullname: "fullName",
  "full name": "fullName",
  contact: "fullName",
  contactname: "fullName",
  "contact name": "fullName",
  name2: "fullName",
  person: "fullName",
  title: "title",
  role: "title",
  jobtitle: "title",
  "job title": "title",
  name: "name",
  business: "name",
  company: "name",
  "company name": "name",
  organization: "name",
  category: "category",
  industry: "category",
  type: "businessType",
  businesstype: "businessType",
  website: "website",
  url: "website",
  domain: "website",
  phone: "phone",
  tel: "phone",
  telephone: "phone",
  address: "addressLine",
  addressline: "addressLine",
  street: "addressLine",
  city: "city",
  region: "region",
  state: "region",
  province: "region",
  country: "country",
  size: "companySize",
  companysize: "companySize",
  employees: "companySize",
  source: "sourceUrl",
  sourceurl: "sourceUrl",
  "source url": "sourceUrl",
  source_url: "sourceUrl",
  foundat: "sourceUrl",
  "found at": "sourceUrl",
};

/** Human-facing spec for the import UI + docs (defined in a client-safe module). */
export { IMPORT_HEADERS_SPEC } from "./import-spec";

// ---------------------------------------------------------------------------
// CSV parsing (RFC-4180-ish: quoted fields, embedded commas/newlines, "" escape).
// ---------------------------------------------------------------------------

export function parseCsv(text: string): { headers: string[]; rows: string[][] } {
  const records: string[][] = [];
  let field = "";
  let row: string[] = [];
  let inQuotes = false;
  const src = (text ?? "").replace(/\r\n?/g, "\n");

  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (inQuotes) {
      if (c === '"') {
        if (src[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field);
      field = "";
    } else if (c === "\n") {
      row.push(field);
      records.push(row);
      row = [];
      field = "";
    } else {
      field += c;
    }
  }
  if (field.length > 0 || row.length > 0) {
    row.push(field);
    records.push(row);
  }

  const nonEmpty = records.filter((r) => r.some((f) => f.trim() !== ""));
  if (nonEmpty.length === 0) return { headers: [], rows: [] };
  const headers = nonEmpty[0].map((h) => h.trim());
  return { headers, rows: nonEmpty.slice(1) };
}

/** Map a parsed CSV (headers + rows) to canonical LeadRow objects. */
export function csvToLeadRows(headers: string[], rows: string[][]): LeadRow[] {
  const cols = headers.map((h) => IMPORT_HEADER_ALIASES[h.trim().toLowerCase()] ?? null);
  return rows.map((r) => {
    const lead: LeadRow = {};
    cols.forEach((field, i) => {
      if (field) lead[field] = (r[i] ?? "").trim();
    });
    return lead;
  });
}

// ---------------------------------------------------------------------------
// Normalisation + validation of a single lead row
// ---------------------------------------------------------------------------

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export type NormalizedLead = {
  email: string;
  domain: string;
  fullName: string;
  title: string;
  business: {
    name: string;
    category: string;
    businessType: string;
    website: string;
    phone: string;
    addressLine: string;
    city: string;
    region: string;
    country: string;
    companySize: string;
  };
  sourceUrl: string;
};

/**
 * Normalise + validate a row. Returns null when there is no usable email — the lead
 * database is keyed on emailable people, so an email-less row can't be a lead. The
 * business name falls back to the email domain so a name-less row still imports.
 */
export function normalizeLeadRow(raw: LeadRow): NormalizedLead | null {
  const email = normalizeEmail(raw.email);
  if (!email || !EMAIL_RE.test(email)) return null;
  const domain = emailDomain(email);
  const website = (raw.website ?? "").trim();
  const name = (raw.name ?? "").trim() || domain;
  return {
    email,
    domain,
    fullName: (raw.fullName ?? "").trim().slice(0, 160),
    title: (raw.title ?? "").trim().slice(0, 120),
    business: {
      name: name.slice(0, 160),
      category: (raw.category ?? "").trim().slice(0, 120),
      businessType: (raw.businessType ?? "").trim().slice(0, 120),
      website: website ? normalizeDomain(website).slice(0, 200) || website.slice(0, 200) : "",
      phone: (raw.phone ?? "").trim().slice(0, 60),
      addressLine: (raw.addressLine ?? "").trim().slice(0, 200),
      city: (raw.city ?? "").trim().slice(0, 120),
      region: (raw.region ?? "").trim().slice(0, 120),
      country: (raw.country ?? "").trim().slice(0, 120),
      companySize: (raw.companySize ?? "").trim().slice(0, 60),
    },
    sourceUrl: (raw.sourceUrl ?? "").trim().slice(0, 300),
  };
}

// ---------------------------------------------------------------------------
// The store the ingest orchestrator drives (Prisma in prod, a fake in tests)
// ---------------------------------------------------------------------------

export type ExistingContact = {
  id: string;
  businessId: string;
  emailStatus: EmailStatusValue | string;
  fullName: string;
  title: string;
};

export interface LeadStore {
  /** Find a contact by NORMALIZED email, or null. */
  findContact(email: string): Promise<ExistingContact | null>;
  /** Is this email (or its domain) on the global suppression list? */
  isSuppressed(email: string): Promise<boolean>;
  /** Create a Business, return its id. */
  createBusiness(data: NormalizedLead["business"], batchId: string | null): Promise<string>;
  /** Create a Contact (status UNVERIFIED), return its id. */
  createContact(
    input: { businessId: string; email: string; fullName: string; title: string },
    batchId: string | null,
  ): Promise<string>;
  /** Fill blank fields on an existing contact (never overwrite non-empty). */
  updateContact(
    id: string,
    input: { fullName?: string; title?: string },
    batchId: string | null,
  ): Promise<void>;
  /** Add a contact to a list, idempotently (no-op if already a member). */
  addToList(contactId: string, listId: string): Promise<void>;
  /**
   * Record a lawful-basis consent row for a newly-created contact. `note`, when given,
   * is the per-contact provenance (the specific URL the email was found on) — kept
   * separate from `source` (a batch-wide label like "script import") so the evidence is
   * checkable contact-by-contact.
   */
  recordConsent(contactId: string, source: string, note?: string): Promise<void>;
}

// ---------------------------------------------------------------------------
// The ingest orchestrator
// ---------------------------------------------------------------------------

export type ImportResult = {
  totalRows: number;
  inserted: number;
  updated: number;
  skippedDead: number;
  skippedDup: number;
  skippedInvalid: number;
  contactIds: string[];
};

export type IngestOptions = {
  store: LeadStore;
  listId: string | null;
  batchId?: string | null;
  recordConsent?: boolean;
  consentSource?: string;
};

/**
 * Ingest normalized-or-raw rows into the lead database, idempotently.
 *
 * For each row (see file header for the full guarantee set): validate → dedup
 * within the file → look up the existing contact → refuse dead/suppressed →
 * update-or-insert → add to the target list. Returns the batch tally.
 */
export async function ingestLeads(rows: LeadRow[], opts: IngestOptions): Promise<ImportResult> {
  const { store, listId, batchId = null, recordConsent = false, consentSource = "bulk import" } = opts;
  const result: ImportResult = {
    totalRows: rows.length,
    inserted: 0,
    updated: 0,
    skippedDead: 0,
    skippedDup: 0,
    skippedInvalid: 0,
    contactIds: [],
  };

  const seen = new Set<string>(); // in-file dedup by normalized email

  for (const raw of rows) {
    const lead = normalizeLeadRow(raw);
    if (!lead) {
      result.skippedInvalid++;
      continue;
    }
    if (seen.has(lead.email)) {
      result.skippedDup++;
      continue;
    }
    seen.add(lead.email);

    const existing = await store.findContact(lead.email);

    if (existing) {
      // NEVER resurrect a dead/suppressed contact.
      if (isDeadStatus(existing.emailStatus) || (await store.isSuppressed(lead.email))) {
        result.skippedDead++;
        continue;
      }
      // Update in place (fill blanks only) + re-add to the list. No duplicate row.
      await store.updateContact(
        existing.id,
        {
          fullName: existing.fullName ? undefined : lead.fullName || undefined,
          title: existing.title ? undefined : lead.title || undefined,
        },
        batchId,
      );
      if (listId) await store.addToList(existing.id, listId);
      result.updated++;
      result.contactIds.push(existing.id);
      continue;
    }

    // Brand-new email: refuse if it's already globally suppressed (opted-out before
    // the contact row existed) — we never add a suppressed address.
    if (await store.isSuppressed(lead.email)) {
      result.skippedDead++;
      continue;
    }

    const businessId = await store.createBusiness(lead.business, batchId);
    const contactId = await store.createContact(
      { businessId, email: lead.email, fullName: lead.fullName, title: lead.title },
      batchId,
    );
    if (listId) await store.addToList(contactId, listId);
    if (recordConsent) await store.recordConsent(contactId, consentSource, lead.sourceUrl || undefined);
    result.inserted++;
    result.contactIds.push(contactId);
  }

  return result;
}

